def parse_csv_line(line):
    fields = []
    current = []
    in_quotes = False
    for char in line:
        if char == '"':
            if in_quotes:
                if len(current) > 0 and current[-1] == '"':
                    current.pop()
                    fields.append(''.join(current))
                    current = []
                else:
                    in_quotes = False
            else:
                in_quotes = True
        elif char == ',' and not in_quotes:
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if current:
        fields.append(''.join(current))
    return fields
